import { Fragment, options } from 'preact';

const RAF_TIMEOUT = 100;
let HAS_RAF = typeof requestAnimationFrame == 'function';

class HookController {
	constructor() {
		this._currentIndex = 0;
		this._currentComponent = null;
		this._previousComponent = null;
		this._currentHook = 0;
		this._afterPaintEffects = [];
		this._empty = [];
		this._prevRaf = undefined;
		this._oldBeforeDiff = options._diff;
		this._oldBeforeRender = options._render;
		this._oldAfterDiff = options.diffed;
		this._oldCommit = options._commit;
		this._oldBeforeUnmount = options.unmount;
		this._hookCursor = 0;
		this._paintQueue = 0;
		this._reducerFlags = 0;
		this._propFlags = 0;
		this._vnodeFlags = 0;
		this._memoFlags = 0;
		this._layoutFlags = 0;
		this._mergeFlags = 0;
	}

	install() {
		const controller = this;
		options._diff = vnode => controller.beforeDiff(vnode);
		options._render = vnode => controller.beforeRender(vnode);
		options.diffed = vnode => controller.afterDiff(vnode);
		options._commit = (vnode, commitQueue) =>
			controller.commitRootHooks(vnode, commitQueue);
		options.unmount = vnode => controller.unmountHooks(vnode);
		options._mergeObjects = (obj, props) => controller.mergeObjects(obj, props);
		options._mergeComponentState = (component, update) =>
			controller.mergeComponentState(component, update);
		options._diffElementProps = (
			dom,
			newProps,
			oldProps,
			isSvg,
			hydrate,
			setProperty
		) =>
			controller.diffElementProps(
				dom,
				newProps,
				oldProps,
				isSvg,
				hydrate,
				setProperty
			);
	}

	beforeDiff(vnode) {
		this.inspectVnodeWork(vnode);
		if (
			typeof vnode.type === 'function' &&
			!vnode._mask &&
			vnode.type !== Fragment
		) {
			vnode._mask =
				(vnode._parent && vnode._parent._mask ? vnode._parent._mask : '') +
				(vnode._parent && vnode._parent._children
					? vnode._parent._children.indexOf(vnode)
					: 0);
		} else if (!vnode._mask) {
			vnode._mask =
				vnode._parent && vnode._parent._mask ? vnode._parent._mask : '';
		}

		this._currentComponent = null;
		if (this._oldBeforeDiff) this._oldBeforeDiff(vnode);
	}

	beforeRender(vnode) {
		if (this._oldBeforeRender) this._oldBeforeRender(vnode);

		this._currentComponent = vnode._component;
		this._currentIndex = 0;
		this.inspectHookWork(this._currentComponent);
		this.inspectEffectWork(
			this._currentComponent && this._currentComponent.__hooks
		);
		this.inspectLayoutWork(this._currentComponent);

		const hooks = this._currentComponent.__hooks;
		if (hooks) {
			if (this._previousComponent === this._currentComponent) {
				hooks._pendingEffects = [];
				this._currentComponent._renderCallbacks = [];
				hooks._list.forEach(hookItem => {
					if (hookItem._nextValue) {
						hookItem._value = hookItem._nextValue;
					}
					hookItem._pendingValue = this._empty;
					hookItem._nextValue = hookItem._pendingArgs = undefined;
				});
			} else {
				hooks._pendingEffects.forEach(hookItem => this.invokeCleanup(hookItem));
				hooks._pendingEffects.forEach(hookItem => this.invokeEffect(hookItem));
				hooks._pendingEffects = [];
			}
		}
		this._previousComponent = this._currentComponent;
	}

	afterDiff(vnode) {
		if (this._oldAfterDiff) this._oldAfterDiff(vnode);

		const c = vnode._component;
		if (c && c.__hooks) {
			if (c.__hooks._pendingEffects.length)
				this.afterPaint(this._afterPaintEffects.push(c));
			c.__hooks._list.forEach(hookItem => {
				if (hookItem._pendingArgs) {
					hookItem._args = hookItem._pendingArgs;
				}
				if (hookItem._pendingValue !== this._empty) {
					hookItem._value = hookItem._pendingValue;
				}
				hookItem._pendingArgs = undefined;
				hookItem._pendingValue = this._empty;
			});
		}
		this._previousComponent = this._currentComponent = null;
	}

	commitRootHooks(vnode, commitQueue) {
		commitQueue.some(component => {
			try {
				component._renderCallbacks.forEach(cb => this.invokeCleanup(cb));
				component._renderCallbacks = component._renderCallbacks.filter(cb =>
					cb._value ? this.invokeEffect(cb) : true
				);
			} catch (e) {
				commitQueue.some(c => {
					if (c._renderCallbacks) c._renderCallbacks = [];
				});
				commitQueue = [];
				options._catchError(e, component._vnode);
			}
		});

		if (this._oldCommit) this._oldCommit(vnode, commitQueue);
	}

	unmountHooks(vnode) {
		if (this._oldBeforeUnmount) this._oldBeforeUnmount(vnode);

		const c = vnode._component;
		if (c && c.__hooks) {
			let hasErrored;
			c.__hooks._list.forEach(s => {
				try {
					this.invokeCleanup(s);
				} catch (e) {
					hasErrored = e;
				}
			});
			c.__hooks = undefined;
			if (hasErrored) options._catchError(hasErrored, c._vnode);
		}
	}

	getHookState(index, type) {
		if (options._hook) {
			options._hook(this._currentComponent, index, this._currentHook || type);
		}
		this._currentHook = 0;

		const hooks =
			this._currentComponent.__hooks ||
			(this._currentComponent.__hooks = {
				_list: [],
				_pendingEffects: []
			});

		if (index >= hooks._list.length) {
			hooks._list.push({ _pendingValue: this._empty });
		}
		this.inspectHookWork(this._currentComponent);
		return hooks._list[index];
	}

	useState(initialState) {
		this._currentHook = 1;
		return this.useReducer(invokeOrReturn, initialState);
	}

	useReducer(reducer, initialState, init) {
		const hookState = this.getHookState(this._currentIndex++, 2);
		hookState._reducer = reducer;
		this.inspectReducerWork(hookState);
		if (!hookState._component) {
			hookState._value = [
				!init ? invokeOrReturn(undefined, initialState) : init(initialState),

				action => {
					const currentValue = hookState._nextValue
						? hookState._nextValue[0]
						: hookState._value[0];
					const nextValue = hookState._reducer(currentValue, action);

					if (currentValue !== nextValue) {
						hookState._nextValue = [nextValue, hookState._value[1]];
						hookState._component.setState({});
					}
				}
			];

			hookState._component = this._currentComponent;
			this.bindReducerScu(hookState, this._currentComponent);
		}

		return hookState._nextValue || hookState._value;
	}

	bindReducerScu(hookState, currentComponent) {
		if (!currentComponent._hasScuFromHooks) {
			currentComponent._hasScuFromHooks = true;
			const prevScu = currentComponent.shouldComponentUpdate;
			const controller = this;
			currentComponent.shouldComponentUpdate = function(p, s, c) {
				return controller.evaluateStatefulHookScu(
					this,
					p,
					s,
					c,
					hookState,
					prevScu
				);
			};
		}
	}

	evaluateStatefulHookScu(component, p, s, c, hookState, prevScu) {
		this.inspectReducerWork(hookState);
		this.inspectMergeWork(component);
		if (!hookState._component.__hooks) return true;

		const stateHooks = hookState._component.__hooks._list.filter(
			x => x._component
		);
		const allHooksEmpty = stateHooks.every(x => !x._nextValue);
		// When we have no updated hooks in the component we invoke the previous SCU or
		// traverse the VDOM tree further.
		if (allHooksEmpty) {
			return prevScu ? prevScu.call(component, p, s, c) : true;
		}

		// We check whether we have components with a nextValue set that
		// have values that aren't equal to one another this pushes
		// us to update further down the tree
		let shouldUpdate = false;
		stateHooks.forEach(hookItem => {
			if (hookItem._nextValue) {
				const currentValue = hookItem._value[0];
				hookItem._value = hookItem._nextValue;
				hookItem._nextValue = undefined;
				if (currentValue !== hookItem._value[0]) shouldUpdate = true;
			}
		});

		return shouldUpdate
			? prevScu
				? prevScu.call(component, p, s, c)
				: true
			: false;
	}

	useEffect(callback, args) {
		const state = this.getHookState(this._currentIndex++, 3);
		this.inspectEffectWork(
			this._currentComponent && this._currentComponent.__hooks
		);
		if (!options._skipEffects && this.haveHookArgsChanged(state._args, args)) {
			state._value = callback;
			state._pendingArgs = args;

			this._currentComponent.__hooks._pendingEffects.push(state);
		}
	}

	useLayoutEffect(callback, args) {
		const state = this.getHookState(this._currentIndex++, 4);
		this.inspectLayoutWork(this._currentComponent);
		if (!options._skipEffects && this.haveHookArgsChanged(state._args, args)) {
			state._value = callback;
			state._pendingArgs = args;

			this._currentComponent._renderCallbacks.push(state);
		}
	}

	useRef(initialValue) {
		this._currentHook = 5;
		return this.useMemo(() => ({ current: initialValue }), []);
	}

	useImperativeHandle(ref, createHandle, args) {
		this._currentHook = 6;
		this.useLayoutEffect(
			() => {
				if (typeof ref == 'function') {
					ref(createHandle());
					return () => ref(null);
				} else if (ref) {
					ref.current = createHandle();
					return () => (ref.current = null);
				}
			},
			args == null ? args : args.concat(ref)
		);
	}

	useMemo(factory, args) {
		const state = this.getHookState(this._currentIndex++, 7);
		this.inspectMemoWork(state);
		if (this.haveHookArgsChanged(state._args, args)) {
			state._pendingValue = factory();
			state._pendingArgs = args;
			state._factory = factory;
			return state._pendingValue;
		}

		return state._value;
	}

	useCallback(callback, args) {
		this._currentHook = 8;
		return this.useMemo(() => callback, args);
	}

	useContext(context) {
		const provider = this._currentComponent.context[context._id];
		const state = this.getHookState(this._currentIndex++, 9);
		state._context = context;
		if (!provider) return context._defaultValue;
		if (state._value == null) {
			state._value = true;
			provider.sub(this._currentComponent);
		}
		return provider.props.value;
	}

	useDebugValue(value, formatter) {
		if (options.useDebugValue) {
			options.useDebugValue(formatter ? formatter(value) : value);
		}
	}

	useErrorBoundary(cb) {
		const state = this.getHookState(this._currentIndex++, 10);
		const errState = this.useState();
		state._value = cb;
		if (!this._currentComponent.componentDidCatch) {
			this._currentComponent.componentDidCatch = (err, errorInfo) => {
				if (state._value) state._value(err, errorInfo);
				errState[1](err);
			};
		}
		return [
			errState[0],
			() => {
				errState[1](undefined);
			}
		];
	}

	hashMask(s) {
		let h = 0,
			i = s.length;
		while (i > 0) {
			h = ((h << 5) - h + s.charCodeAt(--i)) | 0;
		}
		return h;
	}

	useId() {
		const state = this.getHookState(this._currentIndex++, 11);
		if (!state._value) {
			state._value =
				'P' +
				this.hashMask(this._currentComponent._vnode._mask) +
				this._currentIndex;
		}

		return state._value;
	}

	flushAfterPaintEffects() {
		let component;
		while ((component = this._afterPaintEffects.shift())) {
			if (!component._parentDom || !component.__hooks) continue;
			try {
				component.__hooks._pendingEffects.forEach(hookItem =>
					this.invokeCleanup(hookItem)
				);
				component.__hooks._pendingEffects.forEach(hookItem =>
					this.invokeEffect(hookItem)
				);
				component.__hooks._pendingEffects = [];
			} catch (e) {
				component.__hooks._pendingEffects = [];
				options._catchError(e, component._vnode);
			}
		}
	}

	afterNextFrame(callback) {
		const done = () => {
			clearTimeout(timeout);
			if (HAS_RAF) cancelAnimationFrame(raf);
			setTimeout(callback);
		};
		const timeout = setTimeout(done, RAF_TIMEOUT);

		let raf;
		if (HAS_RAF) {
			raf = requestAnimationFrame(done);
		}
	}

	afterPaint(newQueueLength) {
		if (
			newQueueLength === 1 ||
			this._prevRaf !== options.requestAnimationFrame
		) {
			this._prevRaf = options.requestAnimationFrame;
			(this._prevRaf || this.afterNextFrame.bind(this))(() =>
				this.flushAfterPaintEffects()
			);
		}
	}

	invokeCleanup(hook) {
		const comp = this._currentComponent;
		let cleanup = hook._cleanup;
		if (typeof cleanup == 'function') {
			hook._cleanup = undefined;
			cleanup();
		}

		this._currentComponent = comp;
	}

	invokeEffect(hook) {
		const comp = this._currentComponent;
		hook._cleanup = hook._value();
		this._currentComponent = comp;
	}

	haveHookArgsChanged(oldArgs, newArgs) {
		return (
			!oldArgs ||
			oldArgs.length !== newArgs.length ||
			newArgs.some((arg, index) => arg !== oldArgs[index])
		);
	}

	mergeObjects(obj, props) {
		for (let i in props) obj[i] = props[i];
		return obj;
	}

	mergeComponentState(component, update) {
		this.inspectMergeWork(component);
		let s;
		if (
			component._nextState != null &&
			component._nextState !== component.state
