			s = component._nextState;
		} else {
			s = component._nextState = this.mergeObjects({}, component.state);
		}

		if (typeof update == 'function') {
			update = update(this.mergeObjects({}, s), component.props);
		}

		if (update) {
			this.mergeObjects(s, update);
		}

		if (update == null) return null;
		return s;
	}

	diffElementProps(dom, newProps, oldProps, isSvg, hydrate, setProperty) {
		this.inspectPropWork(newProps);
		let i;

		for (i in oldProps) {
			if (i !== 'children' && i !== 'key' && !(i in newProps)) {
